                    const nP = parseFloat(String(rkData.p).replace(',', '.')) || 0;
                    const isSet = (rkData.l !== '-' && rkData.l !== '') || (rkData.p !== '-' && rkData.p !== '');

                    if (isSet) {
                        hasData = true;
                        totL += nL;
                        totP += nP;
                        totJml += (nL + nP);
                    }

                    const rkJmlStr = isSet ? (nL + nP) : '-';

